userContent.text:
Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>Reaction profile <select id="reactionProfileInput" onchange="update_reactionProfile(this.value)"><option>Fast exergonic</option><option>Slow exergonic</option><option>Fast endergonic</option><option>Slow endergonic</option></select></label>
<label>Activation barrier ΔG‡: <output id="activationBarrierVal">2.0</output><input id="activationBarrierInput" type="range" min="1" max="8" step="0.1" value="2" oninput="document.getElementById('activationBarrierVal').value=(+this.value).toFixed(1);update_activationBarrier(+this.value)"></label>
<label>Product energy relative to reactants ΔG°: <output id="productEnergyVal">-3.0</output><input id="productEnergyInput" type="range" min="-4" max="4" step="0.1" value="-3" oninput="document.getElementById('productEnergyVal').value=(+this.value).toFixed(1);update_productEnergy(+this.value)"></label>
<span id="demoNarration" style="display:block;margin:0;font-size:10px;line-height:1.35;max-width:260px">The curve has a small hump and ends below the reactants. The low ΔG‡ indicates a fast reaction, while the negative ΔG° indicates products are thermodynamically favored.</span>
<span style="display:flex;align-items:center;gap:6px"><button onclick="prevStep()">◀</button><span id="stepLabel">1/4: Fast and exergonic</span><button onclick="nextStep()">▶</button></span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 1280, H = 790;
draw.viewbox(0, 0, W, H);
draw.rect(W, H).fill('#ffffff');

var blueField = '#dff2fb';
var magenta = '#e6008d';
var axisBlack = '#111111';
var dashColor = '#222222';
var fastColor = '#2c7fb8';
var thermoColor = '#f28e2b';

var energyGradient = draw.gradient('linear', function (add) {
  add.stop(0, '#fff8b7');
  add.stop(0.53, '#ffd995');
  add.stop(1, '#f36f4d');
});
energyGradient.from(0, 1).to(0, 0);

var presets = {
  'Fast exergonic': { barrier: 2, product: -3 },
  'Slow exergonic': { barrier: 6.5, product: -2 },
  'Fast endergonic': { barrier: 2, product: 1 },
  'Slow endergonic': { barrier: 7, product: 3 }
};

var demoSteps = [
  {
    title: 'Fast and exergonic',
    narration: 'The curve has a small hump and ends below the reactants. The low ΔG‡ indicates a fast reaction, while the negative ΔG° indicates products are thermodynamically favored.',
    state: { reactionProfile: 'Fast exergonic', activationBarrier: 2, productEnergy: -3 }
  },
  {
    title: 'Same downhill direction, slower reaction',
    narration: 'Increasing only the activation barrier makes the reaction slower, even though the product level remains below the reactants. Rate and favorability are not the same quantity.',
    state: { reactionProfile: 'Slow exergonic', activationBarrier: 6.5, productEnergy: -2 }
  },
  {
    title: 'Fast but endergonic',
    narration: 'A shallow barrier can still lead to products that sit above the reactants. This reaction may proceed quickly once started, but its positive ΔG° means products are not thermodynamically favored.',
    state: { reactionProfile: 'Fast endergonic', activationBarrier: 2, productEnergy: 1 }
  },
  {
    title: 'Slow and endergonic',
    narration: 'Here both quantities are unfavorable: the barrier is high and the products are higher in energy than the reactants. The profile combines a slow rate with positive ΔG°.',
    state: { reactionProfile: 'Slow endergonic', activationBarrier: 7, productEnergy: 3 }
  }
];

var state = { profile: 'Fast exergonic', barrier: 2, product: -3 };
var currentStep = 0;
var smallPanels = [];
var largeGroup = draw.group();

function pts(arr) {
  return arr.map(function (p) { return p[0] + ',' + p[1]; }).join(' ');
}

function haloText(parent, text, x, y, size, opts) {
  opts = opts || {};
  var t = parent.text(text)
    .font({
      family: 'Arial, Helvetica, sans-serif',
      size: size,
      weight: opts.weight || 'normal',
      anchor: opts.anchor || 'middle'
    })
    .attr({
      x: x,
      y: y,
      fill: opts.fill || '#000',
      'dominant-baseline': opts.baseline || 'middle',
      'paint-order': 'stroke',
      stroke: opts.halo || '#fff',
      'stroke-width': opts.strokeWidth == null ? 4 : opts.strokeWidth,
      'stroke-linejoin': 'round'
    });
  if (opts.rotate) t.rotate(opts.rotate, x, y);
  return t;
}

function energyY(field, value) {
  var minE = -4.5, maxE = 8;
  var topPad = 30, botPad = 44;
  return field.y + topPad + (maxE - value) / (maxE - minE) * (field.h - topPad - botPad);
}

function profilePath(field, barrier, product) {
  var x0 = field.x + field.w * 0.18;
  var xFlat1 = field.x + field.w * 0.23;
  var xPeak = field.x + field.w * 0.48;
  var xDown = field.x + field.w * 0.68;
  var xFlat2 = field.x + field.w * 0.80;
  var xEnd = field.x + field.w * 0.83;
  var yR = energyY(field, 0);
  var yP = energyY(field, product);
  var yPeak = energyY(field, barrier);
  return 'M ' + x0 + ' ' + yR +
    ' L ' + xFlat1 + ' ' + yR +
    ' C ' + (field.x + field.w * 0.31) + ' ' + yR + ' ' + (field.x + field.w * 0.34) + ' ' + yPeak + ' ' + xPeak + ' ' + yPeak +
    ' C ' + (field.x + field.w * 0.60) + ' ' + yPeak + ' ' + (field.x + field.w * 0.64) + ' ' + yP + ' ' + xDown + ' ' + yP +
    ' L ' + xEnd + ' ' + yP;
}

function drawVerticalDoubleArrow(parent, x, y1, y2, color, width, label, lx, ly, size) {
  var top = Math.min(y1, y2);
  var bottom = Math.max(y1, y2);
  if (Math.abs(bottom - top) < 7) {
    parent.line(x - 9, (top + bottom) / 2, x + 9, (top + bottom) / 2)
      .stroke({ color: color, width: width, linecap: 'round' });
  } else {
    parent.line(x, top + 6, x, bottom - 6)
      .stroke({ color: color, width: width, linecap: 'round' });
    parent.polygon(pts([[x, top], [x - 5, top + 9], [x + 5, top + 9]])).fill(color).stroke('none');
    parent.polygon(pts([[x, bottom], [x - 5, bottom - 9], [x + 5, bottom - 9]])).fill(color).stroke('none');
  }
  var hit = parent.rect(36, Math.max(22, bottom - top + 10)).center(x, (top + bottom) / 2).fill({ color: '#fff', opacity: 0 });
  hit.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip(label + ' is the vertical energy difference shown by this arrow.', e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup(label, label + ' measures an energy difference on this diagram. ΔG‡ is tied to reaction rate, whereas ΔG° is tied to whether products or reactants are lower in energy.');
    });
  haloText(parent, label, lx, ly, size || 20, { fill: '#000', anchor: 'middle' });
}

function drawEnergyArrow(parent, x, y, w, h) {
  var head = 30;
  parent.polygon(pts([
    [x + w * 0.50, y],
    [x + w, y + head],
    [x + w * 0.72, y + head],
    [x + w * 0.72, y + h],
    [x + w * 0.28, y + h],
    [x + w * 0.28, y + head],
    [x, y + head]
  ])).fill(energyGradient).stroke({ color: '#000', width: 1.5 });
  haloText(parent, 'Energy', x + w * 0.50, y + h * 0.57, 22, { weight: 'bold', rotate: -90, strokeWidth: 3 });
}

function drawProgressArrow(parent, field, labelSize) {
  var y = field.y + field.h + 26;
  haloText(parent, 'Reaction progress', field.x + field.w * 0.32, y, labelSize || 22, { anchor: 'middle', strokeWidth: 3 });
  var x1 = field.x + field.w * 0.63, x2 = field.x + field.w * 0.95;
  parent.line(x1, y, x2, y).stroke({ color: magenta, width: 3 });
  parent.polygon(pts([[x2 + 13, y], [x2 - 2, y - 6], [x2 - 2, y + 6]])).fill(magenta).stroke('none');
}

function drawReactionPanel(parent, letter, field, arrowX, barrier, product, name, isLarge, highlightColors) {
  var g = parent.group();

  if (letter) haloText(g, '(' + letter + ')', field.x - 125, field.y + 16, 21, { weight: 'bold', anchor: 'middle', strokeWidth: 3 });

  drawEnergyArrow(g, arrowX, field.y, isLarge ? 38 : 45, field.h);

  g.rect(field.w, field.h).move(field.x, field.y).fill(blueField).stroke('none');
  g.line(field.x, field.y, field.x, field.y + field.h).stroke({ color: axisBlack, width: 2.2 });
  g.line(field.x, field.y + field.h, field.x + field.w, field.y + field.h).stroke({ color: axisBlack, width: 2.2 });

  var yR = energyY(field, 0);
  var yPeak = energyY(field, barrier);
  var yP = energyY(field, product);
  var xStart = field.x + field.w * 0.18;
  var xPeak = field.x + field.w * 0.48;
  var xEnd = field.x + field.w * 0.83;

  g.line(xStart - field.w * 0.09, yR, xStart + field.w * 0.27, yR)
    .stroke({ color: dashColor, width: isLarge ? 1.5 : 1.3 }).attr({ 'stroke-dasharray': '10 6' });
  g.line(xPeak - field.w * 0.24, yPeak, xPeak + field.w * 0.24, yPeak)
    .stroke({ color: dashColor, width: isLarge ? 1.5 : 1.3 }).attr({ 'stroke-dasharray': '10 6' });
  g.line(xEnd - field.w * 0.17, yP, xEnd + field.w * 0.15, yP)
    .stroke({ color: dashColor, width: isLarge ? 1.5 : 1.3 }).attr({ 'stroke-dasharray': '10 6' });

  var curve = g.path(profilePath(field, barrier, product))
    .fill('none')
    .stroke({ color: magenta, width: isLarge ? 5 : 4, linecap: 'round', linejoin: 'round' });
  curve.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip(name + ': barrier controls speed; product height controls ΔG°.', e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup(name, 'This reaction coordinate curve combines two independent quantities. The height from reactants to the transition state is ΔG‡; the height difference between products and reactants is ΔG°.');
    });

  var barrierColor = highlightColors ? fastColor : '#111';
  var dgColor = highlightColors ? thermoColor : '#111';
  var arrW = isLarge ? 1.8 : 1.2;
  drawVerticalDoubleArrow(
    g,
    field.x + field.w * 0.18,
    yR,
    yPeak,
    barrierColor,
    arrW,
    'ΔG‡',
    field.x + field.w * 0.17,
    (yR + yPeak) / 2 + 5,
    isLarge ? 24 : 20
  );

  var dgX = field.x + field.w * (isLarge ? 0.87 : 0.84);
  var dgLabelX = product >= 0 ? dgX + (isLarge ? 1 : -2) : dgX - (isLarge ? 2 : 0);
  drawVerticalDoubleArrow(
    g,
    dgX,
    yR,
    yP,
    dgColor,
    arrW,
    'ΔG°',
    dgLabelX,
    (yR + yP) / 2 + (product >= 0 ? -4 : 4),
    isLarge ? 24 : 20
  );

  drawProgressArrow(g, field, isLarge ? 20 : 22);
  return g;
}

function profileNameFromValues(barrier, product) {
  var speed = barrier <= 4.25 ? 'Fast' : 'Slow';
  var therm = product < 0 ? 'exergonic' : 'endergonic';
  return speed + ' ' + therm;
}

function makeSmallPanels() {
  var configs = [
    { letter: 'a', name: 'Fast exergonic', barrier: 2, product: -3, field: { x: 128, y: 4, w: 350, h: 315 }, arrowX: 52 },
    { letter: 'b', name: 'Slow exergonic', barrier: 6.5, product: -2, field: { x: 620, y: 4, w: 350, h: 315 }, arrowX: 544 },
    { letter: 'c', name: 'Fast endergonic', barrier: 2, product: 1, field: { x: 128, y: 425, w: 350, h: 315 }, arrowX: 52 },
    { letter: 'd', name: 'Slow endergonic', barrier: 7, product: 3, field: { x: 620, y: 425, w: 350, h: 315 }, arrowX: 544 }
  ];

  configs.forEach(function (cfg) {
    var panelG = draw.group();
    drawReactionPanel(panelG, cfg.letter, cfg.field, cfg.arrowX, cfg.barrier, cfg.product, cfg.name, false, false);
    var h = panelG.rect(cfg.field.w + 12, cfg.field.h + 12)
      .move(cfg.field.x - 6, cfg.field.y - 6)
      .fill('none')
      .stroke({ color: '#ffb000', width: 5, linejoin: 'round' });
    h.hide();
    var hit = panelG.rect(cfg.field.w + 130, cfg.field.h + 70)
      .move(cfg.arrowX - 8, cfg.field.y - 3)
      .fill({ color: '#fff', opacity: 0 });
    hit.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('Select ' + cfg.name + '.', e); })
      .on('mouseleave', function () { hideTooltip(); })
      .on('click', function () { update_reactionProfile(cfg.name); });
    smallPanels.push({ name: cfg.name, highlight: h });
  });
}

function renderLargeProfile() {
  largeGroup.clear();
  var field = { x: 1030, y: 95, w: 230, h: 555 };
  drawReactionPanel(largeGroup, '', field, 982, state.barrier, state.product, state.profile, true, true);

  var rateWord = state.barrier <= 4.25 ? 'fast' : 'slow';
  var favWord = state.product < 0 ? 'products lower' : 'products higher';
  var invisibleInfo = largeGroup.rect(field.w, field.h).move(field.x, field.y).fill({ color: '#fff', opacity: 0 });
  invisibleInfo.css('cursor', 'pointer')
    .on('mousemove', function (e) {
      showTooltip('Selected profile: ' + rateWord + ' tendency from ΔG‡; ' + favWord + ' from ΔG°.', e);
    })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup('Independent controls', 'Changing ΔG‡ changes the height of the transition-state barrier and therefore the expected rate. Changing ΔG° moves the product level relative to the reactants and therefore changes thermodynamic favorability.');
    });

  updateHighlights();
}

function updateHighlights() {
  smallPanels.forEach(function (p) {
    if (p.name === state.profile) p.highlight.show();
    else p.highlight.hide();
  });
}

function setControlValues(profile, barrier, product) {
  var profileInput = document.getElementById('reactionProfileInput');
  var barrierInput = document.getElementById('activationBarrierInput');
  var productInput = document.getElementById('productEnergyInput');
  var barrierVal = document.getElementById('activationBarrierVal');
  var productVal = document.getElementById('productEnergyVal');
  if (profileInput) profileInput.value = profile;
  if (barrierInput) barrierInput.value = barrier;
  if (productInput) productInput.value = product;
  if (barrierVal) barrierVal.value = (+barrier).toFixed(1);
  if (productVal) productVal.value = (+product).toFixed(1);
}

function update_reactionProfile(value) {
  var p = presets[value] || presets['Fast exergonic'];
  state.profile = value;
  state.barrier = p.barrier;
  state.product = p.product;
  setControlValues(state.profile, state.barrier, state.product);
  renderLargeProfile();
}

function update_activationBarrier(v) {
  state.barrier = v;
  state.profile = profileNameFromValues(state.barrier, state.product);
  setControlValues(state.profile, state.barrier, state.product);
  renderLargeProfile();
}

function update_productEnergy(v) {
  state.product = v;
  state.profile = profileNameFromValues(state.barrier, state.product);
  setControlValues(state.profile, state.barrier, state.product);
  renderLargeProfile();
}

function applyStep(i) {
  currentStep = (i + demoSteps.length) % demoSteps.length;
  var step = demoSteps[currentStep];
  state.profile = step.state.reactionProfile;
  state.barrier = step.state.activationBarrier;
  state.product = step.state.productEnergy;
  setControlValues(state.profile, state.barrier, state.product);
  var narration = document.getElementById('demoNarration');
  var label = document.getElementById('stepLabel');
  if (narration) narration.textContent = step.narration;
  if (label) label.textContent = (currentStep + 1) + '/' + demoSteps.length + ': ' + step.title;
  renderLargeProfile();
}

function prevStep() {
  applyStep(currentStep - 1);
}

function nextStep() {
  applyStep(currentStep + 1);
}

makeSmallPanels();
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

