function pointString(arr) {
  return arr.map(function (p) { return p[0] + ',' + p[1]; }).join(' ');
}

function label(parent, txt, x, y, size, opts) {
  opts = opts || {};
  var t = parent.text(txt).font({
    family: 'Arial, Helvetica, sans-serif',
    size: size,
    weight: opts.weight || 'normal',
    anchor: opts.anchor || 'middle'
  }).attr({
    x: x,
    y: y,
    fill: opts.fill || '#000',
    'dominant-baseline': opts.baseline || 'middle',
    'paint-order': 'stroke',
    stroke: opts.halo || '#fff',
    'stroke-width': opts.strokeWidth == null ? 4 : opts.strokeWidth,
    'stroke-linejoin': 'round'
  });
  if (opts.rotate) t.rotate(opts.rotate, x, y);
  return t;
}

function energyY(field, value) {
  var minE = -4.6, maxE = 8.1;
  var topPad = 66, botPad = 62;
  return field.y + topPad + (maxE - value) / (maxE - minE) * (field.h - topPad - botPad);
}

function smoothProfilePath(field, barrier, product) {
  var x0 = field.x + field.w * 0.18;
  var x1 = field.x + field.w * 0.25;
  var xp = field.x + field.w * 0.44;
  var x2 = field.x + field.w * 0.62;
  var x3 = field.x + field.w * 0.78;
  var x4 = field.x + field.w * 0.82;
  var yR = energyY(field, 0);
  var yP = energyY(field, product);
  var yPeak = energyY(field, barrier);

  return 'M ' + x0 + ' ' + yR +
    ' C ' + (x0 + field.w * 0.035) + ' ' + yR + ' ' + (x1 - field.w * 0.035) + ' ' + yR + ' ' + x1 + ' ' + yR +
    ' C ' + (field.x + field.w * 0.31) + ' ' + yR + ' ' + (field.x + field.w * 0.35) + ' ' + yPeak + ' ' + xp + ' ' + yPeak +
    ' C ' + (field.x + field.w * 0.53) + ' ' + yPeak + ' ' + (field.x + field.w * 0.55) + ' ' + yP + ' ' + x2 + ' ' + yP +
    ' C ' + (field.x + field.w * 0.67) + ' ' + yP + ' ' + (x3 - field.w * 0.035) + ' ' + yP + ' ' + x3 + ' ' + yP +
    ' L ' + x4 + ' ' + yP;
}

function drawDoubleArrow(parent, x, y1, y2, color, width, txt, lx, ly, size) {
  var top = Math.min(y1, y2);
  var bottom = Math.max(y1, y2);
  if (Math.abs(bottom - top) > 16) {
    parent.line(x, top + 8, x, bottom - 8).stroke({ color: color, width: width, linecap: 'round' });
    parent.polygon(pointString([[x, top], [x - 5.2, top + 9.5], [x + 5.2, top + 9.5]])).fill(color).stroke('none');
    parent.polygon(pointString([[x, bottom], [x - 5.2, bottom - 9.5], [x + 5.2, bottom - 9.5]])).fill(color).stroke('none');
  } else {
    parent.line(x, top, x, bottom).stroke({ color: color, width: width, linecap: 'round' });
  }
  label(parent, txt, lx, ly, size, { strokeWidth: 3 });
  var hit = parent.rect(42, Math.max(32, bottom - top + 20)).center(x, (top + bottom) / 2).fill({ color: '#fff', opacity: 0 });
  hit.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip(txt + ' is the vertical energy difference marked by this arrow.', e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup(txt, txt === 'ΔG‡'
        ? 'ΔG‡ is the activation barrier from reactants to the transition state. A smaller barrier generally corresponds to a faster reaction.'
        : 'ΔG° is the energy difference between products and reactants. Negative ΔG° means products are lower in energy; positive ΔG° means products are higher.');
    });
}

function drawEnergyArrow(parent, x, y, w, h) {
  var headH = 30;
  parent.polygon(pointString([
    [x + w * 0.50, y],
    [x + w, y + headH],
    [x + w * 0.74, y + headH],
    [x + w * 0.74, y + h],
    [x + w * 0.26, y + h],
    [x + w * 0.26, y + headH],
    [x, y + headH]
  ])).fill(energyGradient).stroke({ color: black, width: 1.5, linejoin: 'round' });
  label(parent, 'Energy', x + w * 0.50, y + h * 0.55, 22, { weight: 'bold', rotate: -90, strokeWidth: 3 });
}

function drawProgress(parent, field) {
  var y = field.y + field.h + 21;
  label(parent, 'Reaction progress', field.x + field.w * 0.32, y, 22, { anchor: 'middle', strokeWidth: 4 });
  var x1 = field.x + field.w * 0.63;
  var x2 = field.x + field.w * 0.95;
  parent.line(x1, y, x2, y).stroke({ color: magenta, width: 3 });
  parent.polygon(pointString([[x2 + 13, y], [x2 - 1, y - 6], [x2 - 1, y + 6]])).fill(magenta).stroke('none');
}

function drawPanel(parent, cfg, opts) {
  opts = opts || {};
  var field = cfg.field;
  var barrier = cfg.barrier;
  var product = cfg.product;
  var large = !!opts.large;
  var g = parent.group();

  if (cfg.letter) {
    label(g, '(' + cfg.letter + ')', field.x - 112, field.y + 16, 21, { weight: 'bold', anchor: 'middle', strokeWidth: 4 });
  }

  drawEnergyArrow(g, cfg.arrowX, field.y + 2, large ? 46 : 45, field.h - 2);

  g.rect(field.w, field.h).move(field.x, field.y).fill(blueField).stroke('none');
  g.line(field.x, field.y, field.x, field.y + field.h).stroke({ color: black, width: 2.2 });
  g.line(field.x, field.y + field.h, field.x + field.w, field.y + field.h).stroke({ color: black, width: 2.2 });

  var yR = energyY(field, 0);
  var yPeak = energyY(field, barrier);
  var yP = energyY(field, product);
  var xStart = field.x + field.w * 0.18;
  var xPeak = field.x + field.w * 0.44;
  var xEnd = field.x + field.w * 0.82;

  g.line(xStart - field.w * 0.09, yR, xStart + field.w * 0.28, yR)
    .stroke({ color: dash, width: 1.4 }).attr({ 'stroke-dasharray': '12 6' });
  g.line(xPeak - field.w * 0.26, yPeak, xPeak + field.w * 0.26, yPeak)
    .stroke({ color: dash, width: 1.4 }).attr({ 'stroke-dasharray': '12 6' });
  g.line(xEnd - field.w * 0.17, yP, xEnd + field.w * 0.17, yP)
    .stroke({ color: dash, width: 1.4 }).attr({ 'stroke-dasharray': '12 6' });

  var path = g.path(smoothProfilePath(field, barrier, product))
    .fill('none')
    .stroke({ color: magenta, width: large ? 5 : 4, linecap: 'round', linejoin: 'round' });
  path.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip(cfg.name + ': curve height gives ΔG‡; final level gives ΔG°.', e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      state.profile = cfg.name;
      state.barrier = cfg.barrier;
      state.product = cfg.product;
      setControlValues(state.profile, state.barrier, state.product);
      revealSelection(true);
      renderSelectedOverlay();
    });

  drawDoubleArrow(
    g,
    field.x + field.w * 0.19,
    yR,
    yPeak,
    opts.highlight ? barrierHi : black,
    opts.highlight ? 2.5 : 1.3,
    'ΔG‡',
    field.x + field.w * 0.18,
    (yR + yPeak) / 2 + 4,
    large ? 22 : 20
  );

  var dgX = field.x + field.w * (product >= 0 ? 0.84 : 0.83);
  var labX = product >= 0 ? dgX + field.w * 0.06 : dgX - field.w * 0.03;
  var labY = (yR + yP) / 2 + (product >= 0 ? -3 : 4);
  drawDoubleArrow(
    g,
    dgX,
    yR,
    yP,
    opts.highlight ? dgHi : black,
    opts.highlight ? 2.5 : 1.3,
    'ΔG°',
    labX,
    labY,
    large ? 22 : 20
  );

  drawProgress(g, field);
  return g;
}

