function clamp(v, a, b) {
  return Math.max(a, Math.min(b, v));
}

function levelFractions(name, barrier, product) {
  var fast = barrier <= 4.25;
  var exergonic = product < 0;
  var r, pk, p;

  if (fast && exergonic) {
    r = 0.51;
    pk = r - 0.065 * barrier;
    p = r - 0.065 * product;
  } else if (!fast && exergonic) {
    r = 0.62;
    pk = r - 0.065 * barrier;
    p = r - 0.10 * product;
  } else if (fast && !exergonic) {
    r = 0.64;
