function profilePath(field, name, barrier, product) {
  var lev = levelFractions(name, barrier, product);
  var yR = relY(field, lev.reactant);
  var yP = relY(field, lev.product);
  var yPeak = relY(field, lev.peak);
  var fast = barrier <= 4.25;
  var exergonic = product < 0;

  var x0 = field.x + field.w * 0.18;
  var xFlat = field.x + field.w * 0.235;
  var xPeak = field.x + field.w * (fast && !exergonic ? 0.45 : (!fast && !exergonic ? 0.56 : (!fast ? 0.42 : 0.37)));
  var xProd = field.x + field.w * (fast && !exergonic ? 0.73 : (!fast && !exergonic ? 0.80 : (!fast ? 0.67 : 0.61)));
  var xEnd = field.x + field.w * (exergonic ? 0.77 : 0.82);

  return 'M ' + x0 + ' ' + yR +
    ' L ' + xFlat + ' ' + yR +
    ' C ' + (xFlat + field.w * 0.065) + ' ' + yR + ' ' + (xPeak - field.w * 0.090) + ' ' + yPeak + ' ' + xPeak + ' ' + yPeak +
    ' C ' + (xPeak + field.w * 0.100) + ' ' + yPeak + ' ' + (xProd - field.w * 0.105) + ' ' + yP + ' ' + xProd + ' ' + yP +
    ' L ' + xEnd + ' ' + yP;
}

function drawDoubleArrow(parent, x, y1, y2, color, width, txt, lx, ly, size) {
  var top = Math.min(y1, y2);
  var bottom = Math.max(y1, y2);
  var span = bottom - top;
  if (span > 18) {
    parent.line(x, top + 9, x, bottom - 9).stroke({ color: color, width: width, linecap: 'round' });
    parent.polygon(pointString([[x, top], [x - 5.3, top + 10], [x + 5.3, top + 10]])).fill(color).stroke('none');
    parent.polygon(pointString([[x, bottom], [x - 5.3, bottom - 10], [x + 5.3, bottom - 10]])).fill(color).stroke('none');
  } else {
    parent.line(x, top, x, bottom).stroke({ color: color, width: width, linecap: 'round' });
  }
  label(parent, txt, lx, ly, size, { strokeWidth: 3 });
  parent.rect(48, Math.max(34, span + 24)).center(x, (top + bottom) / 2)
    .fill({ color: '#fff', opacity: 0 })
    .css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip(txt + ' is the vertical energy difference marked by this arrow.', e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup(txt, txt === 'ΔG‡'
        ? 'ΔG‡ is the activation free-energy barrier from reactants to the transition state. Lowering this barrier makes the reaction faster, even if the product level is unchanged.'
        : 'ΔG° compares product energy with reactant energy. Negative ΔG° means products are lower in energy; positive ΔG° means products are higher.');
    });
}

function drawEnergyArrow(parent, x, y, w, h) {
  var headH = 28;
  parent.polygon(pointString([
    [x + w * 0.50, y],
    [x + w, y + headH],
    [x + w * 0.75, y + headH],
    [x + w * 0.75, y + h],
    [x + w * 0.25, y + h],
    [x + w * 0.25, y + headH],
    [x, y + headH]
  ])).fill(energyGradient).stroke({ color: black, width: 1.5, linejoin: 'round' });
  label(parent, 'Energy', x + w * 0.50, y + h * 0.55, 22, { weight: 'bold', rotate: -90, strokeWidth: 3 });
}

function drawProgress(parent, field) {
  var y = field.y + field.h + 22;
  label(parent, 'Reaction progress', field.x + field.w * 0.32, y, 22, { anchor: 'middle', strokeWidth: 4 });
  var x1 = field.x + field.w * 0.63;
  var x2 = field.x + field.w * 0.94;
  parent.line(x1, y, x2, y).stroke({ color: magenta, width: 3 });
  parent.polygon(pointString([[x2 + 13, y], [x2 - 1, y - 6], [x2 - 1, y + 6]])).fill(magenta).stroke('none');
}

function drawDashedGuide(parent, x1, x2, y) {
  parent.line(x1, y, x2, y)
    .stroke({ color: dash, width: 1.25, linecap: 'butt' })
    .attr({ 'stroke-dasharray': '12 6' });
}

function drawPanel(parent, cfg, opts) {
  opts = opts || {};
  var field = cfg.field;
  var barrier = cfg.barrier;
  var product = cfg.product;
  var large = !!opts.large;
  var selected = !!opts.selected;
  var g = parent.group();

  if (cfg.letter) {
    label(g, '(' + cfg.letter + ')', field.x - 111, field.y + 17, 21, { weight: 'bold', strokeWidth: 4 });
  }

  drawEnergyArrow(g, cfg.arrowX, field.y + 2, large ? 42 : 34, field.h - 2);

  var bg = g.rect(field.w, field.h).move(field.x, field.y).fill(blueField).stroke('none');
  bg.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Click to select ' + cfg.name + '.', e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () { update_reactionProfile(cfg.name, true); });

  g.line(field.x, field.y, field.x, field.y + field.h).stroke({ color: black, width: 2.2 });
  g.line(field.x, field.y + field.h, field.x + field.w, field.y + field.h).stroke({ color: black, width: 2.2 });

  var lev = levelFractions(cfg.name, barrier, product);
  var yR = relY(field, lev.reactant);
  var yPeak = relY(field, lev.peak);
  var yP = relY(field, lev.product);

  var xStart = field.x + field.w * 0.18;
  var xPeak = field.x + field.w * ((barrier <= 4.25 && product >= 0) ? 0.45 : (barrier > 4.25 && product >= 0 ? 0.56 : (barrier > 4.25 ? 0.42 : 0.37)));
  var xEnd = field.x + field.w * (product < 0 ? 0.77 : 0.82);

  drawDashedGuide(g, xStart - field.w * 0.09, xStart + field.w * 0.30, yR);
  drawDashedGuide(g, xPeak - field.w * 0.27, xPeak + field.w * 0.26, yPeak);
  drawDashedGuide(g, xEnd - field.w * 0.16, xEnd + field.w * 0.17, yP);

  var path = g.path(profilePath(field, cfg.name, barrier, product))
    .fill('none')
    .stroke({ color: magenta, width: large ? 5 : 4, linecap: 'round', linejoin: 'round' });
  path.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip(cfg.name + ': ΔG‡ controls rate; ΔG° controls product vs. reactant energy.', e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () { update_reactionProfile(cfg.name, true); });

  var dgBarrierX = field.x + field.w * 0.19;
  drawDoubleArrow(
    g,
    dgBarrierX,
    yR,
    yPeak,
    selected ? barrierHi : black,
    selected ? 2.5 : 1.25,
    'ΔG‡',
    dgBarrierX - field.w * 0.02,
    (yR + yPeak) / 2 + (large ? 2 : 3),
    large ? 22 : 20
  );

  var dgX, labX, labY;
  if (product < 0) {
    dgX = field.x + field.w * 0.48;
    labX = dgX - field.w * 0.04;
    labY = (yR + yP) / 2;
  } else {
    dgX = field.x + field.w * 0.84;
    labX = dgX + field.w * 0.04;
    labY = (yR + yP) / 2 - 1;
  }
  drawDoubleArrow(
    g,
    dgX,
    yR,
    yP,
    selected ? dgHi : black,
    selected ? 2.5 : 1.25,
    'ΔG°',
    labX,
    labY,
    large ? 22 : 20
  );

  drawProgress(g, field);

  if (selected && !large) {
    g.rect(field.w + 12, field.h + 12)
      .move(field.x - 6, field.y - 6)
      .fill('none')
      .stroke({ color: '#ffb000', width: 4, linejoin: 'round' })
      .back();
  }

  return g;
}

var panelConfigs = [
  { letter: 'a', name: 'Fast exergonic', barrier: 2, product: -3, field: { x: 128, y: 2, w: 346, h: 335 }, arrowX: 52 },
  { letter: 'b', name: 'Slow exergonic', barrier: 6.5, product: -2, field: { x: 622, y: 2, w: 346, h: 335 }, arrowX: 546 },
  { letter: 'c', name: 'Fast endergonic', barrier: 2, product: 1, field: { x: 128, y: 425, w: 346, h: 335 }, arrowX: 52 },
  { letter: 'd', name: 'Slow endergonic', barrier: 7, product: 3, field: { x: 622, y: 425, w: 346, h: 335 }, arrowX: 546 }
];

function effectivePanelConfig(cfg) {
  var out = {
    letter: cfg.letter,
    name: cfg.name,
    barrier: cfg.barrier,
    product: cfg.product,
    field: cfg.field,
    arrowX: cfg.arrowX
  };
  if (cfg.name === state.profile) {
    out.barrier = state.barrier;
    out.product = state.product;
  }
  return out;
}

function renderAllPanels() {
  panelsLayer.clear();
  panelConfigs.forEach(function (base) {
    var cfg = effectivePanelConfig(base);
    drawPanel(panelsLayer, cfg, { selected: selectionShown && base.name === state.profile });
  });
  selectedOverlay.front();
}

function renderSelectedOverlay() {
  selectedOverlay.clear().show().front();
  selectedOverlay.rect(W, H)
    .fill({ color: '#ffffff', opacity: 0.78 })
    .css('cursor', 'pointer')
    .on('click', function () { selectedOverlay.hide(); });

  selectedOverlay.rect(486, 440).move(244, 174).rx(8)
    .fill('#ffffff')
    .stroke({ color: '#c7c7c7', width: 1.5 });

  var cfg = {
    letter: '',
    name: state.profile,
    barrier: state.barrier,
    product: state.product,
    field: { x: 344, y: 220, w: 304, h: 286 },
    arrowX: 286
  };
  label(selectedOverlay, state.profile, 487, 196, 20, { weight: 'bold', strokeWidth: 4 });
  drawPanel(selectedOverlay, cfg, { large: true, selected: true });

  var close = selectedOverlay.group();
  close.rect(72, 28).move(638, 573).rx(4).fill('#f5f5f5').stroke({ color: '#999', width: 1 });
  label(close, 'close', 674, 587, 14, { strokeWidth: 2 });
  close.css('cursor', 'pointer').on('click', function () { selectedOverlay.hide(); });
}

function trigger_selectedView() {
  selectionShown = true;
  renderAllPanels();
  renderSelectedOverlay();
}

function profileNameFromValues(barrier, product) {
  return (barrier <= 4.25 ? 'Fast' : 'Slow') + ' ' + (product < 0 ? 'exergonic' : 'endergonic');
}

function setControlValues(profile, barrier, product) {
  var p = document.getElementById('reactionProfileInput');
  var b = document.getElementById('activationBarrierInput');
  var e = document.getElementById('productEnergyInput');
  var bv = document.getElementById('activationBarrierVal');
  var ev = document.getElementById('productEnergyVal');
  if (p) p.value = profile;
  if (b) b.value = barrier;
  if (e) e.value = product;
  if (bv) bv.value = (+barrier).toFixed(1);
  if (ev) ev.value = (+product).toFixed(1);
}

function update_reactionProfile(value, userAction) {
  var p = presets[value] || presets['Fast exergonic'];
  state.profile = value;
  state.barrier = p.barrier;
  state.product = p.product;
  setControlValues(state.profile, state.barrier, state.product);
  selectionShown = !!userAction;
  renderAllPanels();
  if (selectedOverlay.visible()) renderSelectedOverlay();
  if (userAction) {
    showPopup('Selected profile', 'This preset combines a barrier height, ΔG‡, with a product-reactant energy difference, ΔG°. Use the sliders to change either quantity independently and watch the selected small panel redraw immediately.');
  }
}

function update_activationBarrier(v) {
  state.barrier = v;
  state.profile = profileNameFromValues(state.barrier, state.product);
  setControlValues(state.profile, state.barrier, state.product);
  selectionShown = true;
  renderAllPanels();
  if (selectedOverlay.visible()) renderSelectedOverlay();
}

function update_productEnergy(v) {
  state.product = v;
  state.profile = profileNameFromValues(state.barrier, state.product);
  setControlValues(state.profile, state.barrier, state.product);
  selectionShown = true;
  renderAllPanels();
  if (selectedOverlay.visible()) renderSelectedOverlay();
}

function applyStep(i) {
  currentStep = (i + demoSteps.length) % demoSteps.length;
  var step = demoSteps[currentStep];
  state.profile = step.state.reactionProfile;
  state.barrier = step.state.activationBarrier;
  state.product = step.state.productEnergy;
  setControlValues(state.profile, state.barrier, state.product);

  var narration = document.getElementById('demoNarration');
  var stepLabel = document.getElementById('stepLabel');
  if (narration) narration.textContent = step.narration;
  if (stepLabel) stepLabel.textContent = (currentStep + 1) + '/' + demoSteps.length + ': ' + step.title;

  selectionShown = currentStep !== 0;
  selectedOverlay.hide();
  renderAllPanels();
}

function prevStep() {
  applyStep(currentStep - 1);
}

function nextStep() {
  applyStep(currentStep + 1);
}

renderAllPanels();
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

